window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-db5c2951827f50c9"]={"versions": [{"id": "FIG-db5c2951827f50c9", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Allokationsdiagramm für ein Multicore-Steuergerät (ECU) im Kontext von AUTOSAR Classic Platform (ECU State Manager Fixed / EcuMFixed). Es stellt die Verteilung von Software-Komponenten (SWCs) und Basissoftware-Modulen (BSW) über zwei Prozessorkerne (Core 0 als Master, Core 1 als Slave) auf einem gemeinsamen Mikrocontroller (µC) sowie die vermittelnde Rolle der Runtime Environment (RTE) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hardware-Ebene</strong>: Microcontroller (µC), aufgeteilt in zwei Ausführungskerne: <code>core 0:</code> und <code>core 1:</code>.</li>\n<li><strong>Core 0 (Master-Kern)</strong>:</li>\n<li><strong>Applikationsebene</strong>: <code>SWC 1</code> und <code>SWC 2</code> (mit der Rolle <code>EcuM User</code>).</li>\n<li><strong>BSW-Ebene</strong>: <code>BswM</code> (Basic Software Mode Manager), <code>EcuM Master</code> (ECU State Manager Master), <code>OS</code> (Operating System) sowie <code>Other BSW modules</code>.</li>\n<li><strong>Core 1 (Slave-Kern)</strong>:</li>\n<li><strong>Applikationsebene</strong>: <code>SWC 3</code> (mit der Rolle <code>EcuM User</code>) und <code>SWC 4</code>.</li>\n<li><strong>BSW-Ebene</strong>: <code>BswM</code>, <code>EcuM Slave</code> (ECU State Manager Slave) und <code>OS</code>. Auf Core 1 befinden sich keine weiteren BSW-Module.</li>\n<li><strong>Kommunikation & Schnittstellen</strong>:</li>\n<li><code>RTE</code> (Runtime Environment): Kernübergreifende Zwischenschicht.</li>\n<li><code>Service Interfaces</code>: Verbindungsleitungen über die RTE von <code>SWC 2</code> (Core 0) und <code>SWC 3</code> (Core 1) sowie vom <code>BswM</code> (Core 0) exklusiv zum <code>EcuM Master</code> auf Core 0. Der <code>EcuM Slave</code> besitzt keine Service-Interface-Verbindungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Statische und dynamische Service-Anfragen von EcuM-Benutzern (<code>SWC 2</code> auf Core 0, <code>SWC 3</code> auf Core 1) sowie vom <code>BswM</code> werden über RTE Service Interfaces zentral an den <code>EcuM Master</code> auf Core 0 geleitet.</li>\n<li>Der Master-Kern übernimmt das globale Zustandsmanagement sowie die Evaluierung von Run-Requests.</li>\n<li>Der <code>EcuM Slave</code> auf Core 1 verfügt über keine exponierten Service-Schnittstellen zur RTE; er agiert ohne direkte Service-Anbindung durch SWCs und wird primär für die kernübergreifende Synchronisation bei Zustandsübergängen (Startup, Shutdown, Sleep) genutzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Restriktion (SWS_EcuM_04094)</strong>: Ein EcuM Slave stellt keine Service-Interfaces bereit. Alle Service-Anfragen von SWCs (unabhängig davon, auf welchem Kern sie allokiert sind) müssen durch die RTE an die Master-Instanz geroutet werden.</li>\n<li><strong>Arbitrierung & Wakeup</strong>: Arbitrierung von RUN-Requests und die Auswertung von Wakeup-Events finden ausschließlich auf dem Master-Core statt.</li>\n<li><strong>RTE-Konfiguration</strong>: Die RTE muss Inter-Core-Kommunikation für Service-Interfaces von Slave-Core-SWCs (<code>SWC 3</code>) zum <code>EcuM Master</code> konfigurieren und unterstützen.</li>\n</ul>"}, {"id": "FIG-b88d940cefead7b7", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Allokationsdiagramm für ein Multicore-Steuergerät (ECU) im Kontext von AUTOSAR Classic Platform (ECU State Manager Fixed / EcuMFixed). Es stellt die Verteilung von Software-Komponenten (SWCs) und Basissoftware-Modulen (BSW) über zwei Prozessorkerne (Core 0 als Master, Core 1 als Slave) auf einem gemeinsamen Mikrocontroller (µC) sowie die vermittelnde Rolle der Runtime Environment (RTE) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hardware-Ebene</strong>: Microcontroller (µC), aufgeteilt in zwei Ausführungskerne: <code>core 0:</code> und <code>core 1:</code>.</li>\n<li><strong>Core 0 (Master-Kern)</strong>:</li>\n<li><strong>Applikationsebene</strong>: <code>SWC 1</code> und <code>SWC 2</code> (mit der Rolle <code>EcuM User</code>).</li>\n<li><strong>BSW-Ebene</strong>: <code>BswM</code> (Basic Software Mode Manager), <code>EcuM Master</code> (ECU State Manager Master), <code>OS</code> (Operating System) sowie <code>Other BSW modules</code>.</li>\n<li><strong>Core 1 (Slave-Kern)</strong>:</li>\n<li><strong>Applikationsebene</strong>: <code>SWC 3</code> (mit der Rolle <code>EcuM User</code>) und <code>SWC 4</code>.</li>\n<li><strong>BSW-Ebene</strong>: <code>BswM</code>, <code>EcuM Slave</code> (ECU State Manager Slave) und <code>OS</code>. Auf Core 1 befinden sich keine weiteren BSW-Module.</li>\n<li><strong>Kommunikation & Schnittstellen</strong>:</li>\n<li><code>RTE</code> (Runtime Environment): Kernübergreifende Zwischenschicht.</li>\n<li><code>Service Interfaces</code>: Verbindungsleitungen über die RTE von <code>SWC 2</code> (Core 0) und <code>SWC 3</code> (Core 1) sowie vom <code>BswM</code> (Core 0) exklusiv zum <code>EcuM Master</code> auf Core 0. Der <code>EcuM Slave</code> besitzt keine Service-Interface-Verbindungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Statische und dynamische Service-Anfragen von EcuM-Benutzern (<code>SWC 2</code> auf Core 0, <code>SWC 3</code> auf Core 1) sowie vom <code>BswM</code> werden über RTE Service Interfaces zentral an den <code>EcuM Master</code> auf Core 0 geleitet.</li>\n<li>Der Master-Kern übernimmt das globale Zustandsmanagement sowie die Evaluierung von Run-Requests.</li>\n<li>Der <code>EcuM Slave</code> auf Core 1 verfügt über keine exponierten Service-Schnittstellen zur RTE; er agiert ohne direkte Service-Anbindung durch SWCs und wird primär für die kernübergreifende Synchronisation bei Zustandsübergängen (Startup, Shutdown, Sleep) genutzt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Restriktion (SWS_EcuM_04094)</strong>: Ein EcuM Slave stellt keine Service-Interfaces bereit. Alle Service-Anfragen von SWCs (unabhängig davon, auf welchem Kern sie allokiert sind) müssen durch die RTE an die Master-Instanz geroutet werden.</li>\n<li><strong>Arbitrierung & Wakeup</strong>: Arbitrierung von RUN-Requests und die Auswertung von Wakeup-Events finden ausschließlich auf dem Master-Core statt.</li>\n<li><strong>RTE-Konfiguration</strong>: Die RTE muss Inter-Core-Kommunikation für Service-Interfaces von Slave-Core-SWCs (<code>SWC 3</code>) zum <code>EcuM Master</code> konfigurieren und unterstützen.</li>\n</ul>"}], "trans": [{"from": "FIG-db5c2951827f50c9", "to": "FIG-b88d940cefead7b7", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
